// Accumulate one JSON object without waiting on a Stream. Quoted braces and
// escaped quotes do not terminate a frame. Oversize objects are drained whole.
template<size_t Capacity> class SerialJsonFrame {
public:
  char data[Capacity + 1] = {};
  size_t length = 0;
  bool active = false, ready = false, overflow = false;
  uint32_t lastByteMs = 0;

  void reset() {
    length = depth = 0;
    active = ready = overflow = quoted = escaped = false;
  }
  void push(char c, uint32_t now) {
    if (ready) return;
    if (!active) {
      if (c != '{') return;
      active = true;
    }
    lastByteMs = now;
    if (length < Capacity) data[length++] = c;
    else overflow = true;
    if (quoted) {
      if (escaped) escaped = false;
      else if (c == '\\') escaped = true;
      else if (c == '"') quoted = false;
    } else if (c == '"') quoted = true;
    else if (c == '{') ++depth;
    else if (c == '}' && --depth == 0) {
      data[length] = '\0';
      active = false;
      ready = true;
    }
  }
private:
  size_t depth = 0;
  bool quoted = false, escaped = false;
};
